// ciCellOf renders the CI column for one row, the way the table would.
func ciCellOf(t *testing.T, target scanTarget) string {
	t.Helper()
	for _, col := range inventoryColumns(true) {
		if col.Title == "CI" {
			return col.Cell(target)
		}
	}
